export const BETA_ACCESS_PROFILE = "neuvetra.beta-access.synthetic-rehearsal.v1" as const
export const BETA_ACCESS_SCHEMA_VERSION = 1 as const
export const BETA_ACCESS_TOKEN_BYTES = 32
export const BETA_ACCESS_TOKEN_PATTERN = /^[0-9a-f]{64}$/
export const BETA_ACCESS_UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
export const BETA_ACCESS_EMAIL_PATTERN = /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/

export type BetaRole = "owner" | "member"
export type BetaAccessState = "access_admitted_setup_pending"

export interface BetaAccessRecord {
  companyId: string
  role: BetaRole
  membershipGeneration: number
  state: BetaAccessState
  displayLabel?: string
}

export interface BetaRedeemRequest { token: string; requestId: string }

export function normalizeBetaEmail(email: string): string {
  const normalized = email.trim().toLowerCase()
  if (!BETA_ACCESS_EMAIL_PATTERN.test(normalized) || !/^[\x00-\x7f]+$/.test(normalized) || normalized.length > 254) throw new Error("Verified email required.")
  return normalized
}

export function parseBetaRedeemRequest(value: unknown): BetaRedeemRequest {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Invalid request.")
  const record = value as Record<string, unknown>
  if (Object.keys(record).sort().join(",") !== "requestId,token" || typeof record.token !== "string" || typeof record.requestId !== "string" || !BETA_ACCESS_TOKEN_PATTERN.test(record.token) || !BETA_ACCESS_UUID_PATTERN.test(record.requestId)) throw new Error("Invalid request.")
  return { token: record.token, requestId: record.requestId }
}

import type { WorkspaceConnection } from "./workspace"
import { createPostgresConnection } from "./hosted"
import { BETA_ACCESS_PROFILE, BETA_ACCESS_SCHEMA_VERSION, normalizeBetaEmail, type BetaAccessRecord, type BetaRole } from "./beta-access-contract"

interface AccessRow {
  company_id: string
  role: BetaRole
  membership_generation: number | string
  display_label?: string
  state: "access_admitted_setup_pending"
  replayed?: boolean
}

function mapAccess(row: AccessRow): BetaAccessRecord {
  const generation = Number(row.membership_generation)
  if (!Number.isSafeInteger(generation) || generation < 1) throw new Error("Beta access response is invalid.")
  return { companyId: row.company_id, role: row.role, membershipGeneration: generation, state: row.state, ...(row.display_label === undefined ? {} : { displayLabel: row.display_label }) }
}

function requireUuid(value: string, label: string): void {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)) throw new Error(`${label} is invalid.`)
}

export type BetaDatabaseErrorKind = "conflict" | "unavailable" | "dependency"
export class BetaDatabaseError extends Error {
  constructor(readonly kind: BetaDatabaseErrorKind) { super(kind) }
}

function classify(error: unknown): never {
  const code = typeof error === "object" && error !== null && "code" in error ? String((error as { code: unknown }).code) : ""
  if (code === "23505") throw new BetaDatabaseError("conflict")
  if (code === "P0002") throw new BetaDatabaseError("unavailable")
  throw new BetaDatabaseError("dependency")
}

export class BetaAccessDatabase {
  private constructor(private readonly db: WorkspaceConnection) {}

  static async create(options: { connectionString: string; databaseName: string; runtimeRole: string }): Promise<BetaAccessDatabase> {
    const url = new URL(options.connectionString)
    if (url.protocol !== "postgres:" && url.protocol !== "postgresql:") throw new Error("Local beta database target required.")
    if (url.hostname !== "127.0.0.1" || url.port !== "55472" || decodeURIComponent(url.username) !== options.runtimeRole || decodeURIComponent(url.pathname.slice(1)) !== options.databaseName || !options.databaseName.startsWith("m80_beta_access_") || !options.runtimeRole.startsWith("m80_beta_access_runtime_") || url.search || url.hash) throw new Error("Local beta database target required.")
    const database = new BetaAccessDatabase(createPostgresConnection(options.connectionString, { maxConnections: 4, tls: false }))
    try { await database.checkReadiness(); return database } catch { await database.close(); throw new Error("Beta access dependency is unavailable.") }
  }

  private async asActor<T>(actorId: string, verifiedEmail: string, operation: (db: WorkspaceConnection) => Promise<T>): Promise<T> {
    requireUuid(actorId, "Actor")
    const email = normalizeBetaEmail(verifiedEmail)
    try {
      return await this.db.transaction(async tx => {
        await tx.query("select set_config('request.jwt.claim.sub',$1,true)", [actorId])
        await tx.query("select set_config('request.jwt.claim.email',$1,true)", [email])
        return operation({ ...tx, transaction: async callback => callback(tx), close: async () => {} })
      })
    } catch (error) { classify(error) }
  }

  async checkReadiness() {
    try {
      await this.db.transaction(async tx => {
        await tx.query("select set_config('request.jwt.claim.sub','',true)")
        await tx.query("select * from neuvetra_beta.read_session()")
      })
      return { profile: BETA_ACCESS_PROFILE, schemaVersion: BETA_ACCESS_SCHEMA_VERSION }
    } catch (error) { classify(error) }
  }

  async redeem(actorId: string, verifiedEmail: string, tokenDigest: string, requestId: string): Promise<{ access: BetaAccessRecord; replayed: boolean }> {
    requireUuid(requestId, "Request")
    return this.asActor(actorId, verifiedEmail, async tx => {
      const result = await tx.query<AccessRow>("select * from neuvetra_beta.redeem_invitation($1,$2,$3)", [tokenDigest, requestId, normalizeBetaEmail(verifiedEmail)])
      if (result.rows.length !== 1) throw new Error("Beta access response is invalid.")
      return { access: mapAccess(result.rows[0]!), replayed: result.rows[0]!.replayed === true }
    })
  }

  async readSession(actorId: string, verifiedEmail: string): Promise<BetaAccessRecord[]> {
    return this.asActor(actorId, verifiedEmail, async tx => (await tx.query<AccessRow>("select * from neuvetra_beta.read_session()")).rows.map(mapAccess))
  }

  async readWorkspace(actorId: string, verifiedEmail: string, companyId: string): Promise<BetaAccessRecord | null> {
    requireUuid(companyId, "Company")
    return this.asActor(actorId, verifiedEmail, async tx => {
      const rows = (await tx.query<AccessRow>("select * from neuvetra_beta.read_workspace($1)", [companyId])).rows
      return rows.length === 1 ? mapAccess(rows[0]!) : null
    })
  }

  async close(): Promise<void> { await this.db.close() }
}

export interface SyntheticBetaTenant {
  companyId: string
  admissionId: string
  displayLabel: string
  fixtureManifestSha256: string
}

export interface SyntheticBetaFixtureManifest {
  sha256: string
  tenants: readonly SyntheticBetaTenant[]
  identities: readonly string[]
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`
  const record = value as Record<string, unknown>
  return `{${Object.keys(record).sort().map(key => `${JSON.stringify(key)}:${canonicalJson(record[key])}`).join(",")}}`
}

export function syntheticBetaFixtureManifestSha256(manifest: SyntheticBetaFixtureManifest): string {
  const payload = {
    profile: "neuvetra.beta-access.synthetic-fixture-manifest.v1",
    identities: [...manifest.identities],
    tenants: manifest.tenants.map(({ companyId, admissionId, displayLabel }) => ({ companyId, admissionId, displayLabel })),
  }
  return new Bun.CryptoHasher("sha256").update(canonicalJson(payload)).digest("hex")
}

function assertFixtureTenant(manifest: SyntheticBetaFixtureManifest, tenant: SyntheticBetaTenant): void {
  const exact = manifest.tenants.find(value => value.companyId === tenant.companyId)
  const identities = manifest.identities.map(normalizeBetaEmail)
  if (Object.keys(manifest).sort().join(",") !== "identities,sha256,tenants" || manifest.tenants.some(value => Object.keys(value).sort().join(",") !== "admissionId,companyId,displayLabel,fixtureManifestSha256")
    || !exact || JSON.stringify(exact) !== JSON.stringify(tenant) || tenant.fixtureManifestSha256 !== manifest.sha256 || syntheticBetaFixtureManifestSha256(manifest) !== manifest.sha256
    || identities.some(email => !email.endsWith(".invalid")) || new Set(identities).size !== identities.length
    || new Set(manifest.tenants.map(value => value.companyId)).size !== manifest.tenants.length || new Set(manifest.tenants.map(value => value.admissionId)).size !== manifest.tenants.length) throw new Error("Exact synthetic tenant manifest required.")
}

/** Operator-only: admits one exact tenant from the in-process synthetic fixture manifest. */
export async function admitBetaTenant(db: WorkspaceConnection, manifest: SyntheticBetaFixtureManifest, tenant: SyntheticBetaTenant, decisionReference: string): Promise<void> {
  assertFixtureTenant(manifest, tenant); requireUuid(tenant.companyId, "Company"); requireUuid(tenant.admissionId, "Admission")
  await db.transaction(async tx => {
    const target = await tx.query<{ fixture_manifest_sha256: string }>("select fixture_manifest_sha256 from neuvetra_beta.target for update")
    if (target.rows[0]?.fixture_manifest_sha256 !== manifest.sha256) throw new Error("Synthetic fixture manifest mismatch.")
    await tx.query("insert into neuvetra_beta.tenant_admissions(company_id,admission_id,fixture_manifest_sha256,display_label,data_classification) values($1,$2,$3,$4,'synthetic_rehearsal')", [tenant.companyId, tenant.admissionId, manifest.sha256, tenant.displayLabel])
    await tx.query("insert into neuvetra_beta.audit(id,event_type,company_id,decision_reference) values($1,'admission_created',$2,$3)", [crypto.randomUUID(), tenant.companyId, decisionReference])
  })
}

/** Operator-only. The raw token exists only in the returned in-memory value. */
export async function issueBetaInvitation(db: WorkspaceConnection, manifest: SyntheticBetaFixtureManifest, input: { companyId: string; recipientEmail: string; role: BetaRole; decisionReference: string }): Promise<{ invitationId: string; token: string }> {
  const tenant = manifest.tenants.find(value => value.companyId === input.companyId)
  if (!tenant) throw new Error("Exact synthetic tenant manifest required.")
  assertFixtureTenant(manifest, tenant)
  const email = normalizeBetaEmail(input.recipientEmail)
  if (!email.endsWith(".invalid") || !manifest.identities.includes(email) || !["owner", "member"].includes(input.role)) throw new Error("Exact synthetic identity required.")
  const token = Buffer.from(crypto.getRandomValues(new Uint8Array(32))).toString("hex")
  const digest = new Bun.CryptoHasher("sha256").update(token).digest("hex")
  const invitationId = crypto.randomUUID()
  await db.transaction(async tx => {
    const admission = await tx.query<{ company_id: string }>("select company_id from neuvetra_beta.tenant_admissions where company_id=$1 and admission_id=$2 and fixture_manifest_sha256=$3 and active and tombstoned_at is null for update", [input.companyId, tenant.admissionId, manifest.sha256])
    if (admission.rows.length !== 1) throw new Error("Admission unavailable.")
    await tx.query("insert into neuvetra_beta.invitations(id,company_id,admission_id,token_digest,recipient_email,role,expires_at,issuer_decision_reference) values($1,$2,$3,$4,$5,$6,clock_timestamp()+interval '24 hours',$7)", [invitationId, input.companyId, tenant.admissionId, digest, email, input.role, input.decisionReference])
    await tx.query("insert into neuvetra_beta.audit(id,event_type,company_id,invitation_id,decision_reference) values($1,'invitation_issued',$2,$3,$4)", [crypto.randomUUID(), input.companyId, invitationId, input.decisionReference])
  })
  return { invitationId, token }
}

export async function revokeBetaInvitation(db: WorkspaceConnection, invitationId: string, decisionReference: string): Promise<void> {
  requireUuid(invitationId, "Invitation")
  await db.transaction(async tx => {
    const candidate = await tx.query<{ company_id: string }>("select company_id from neuvetra_beta.invitations where id=$1", [invitationId])
    if (candidate.rows.length !== 1) throw new Error("Invitation unavailable.")
    await tx.query("select company_id from neuvetra_beta.tenant_admissions where company_id=$1 for update", [candidate.rows[0]!.company_id])
    const rows = await tx.query<{ company_id: string }>("update neuvetra_beta.invitations set status='revoked' where id=$1 and status='pending' returning company_id", [invitationId])
    if (rows.rows.length !== 1) throw new Error("Invitation unavailable.")
    await tx.query("insert into neuvetra_beta.audit(id,event_type,company_id,invitation_id,decision_reference) values($1,'invitation_revoked',$2,$3,$4)", [crypto.randomUUID(), rows.rows[0]!.company_id, invitationId, decisionReference])
  })
}

export async function revokeBetaMembership(db: WorkspaceConnection, companyId: string, actorId: string, decisionReference: string): Promise<void> {
  requireUuid(companyId, "Company"); requireUuid(actorId, "Actor")
  await db.transaction(async tx => {
    await tx.query("select pg_advisory_xact_lock(hashtextextended($1::text,80253))", [actorId])
    const rows = await tx.query<{ generation: string }>("update neuvetra_beta.memberships set active=false,revoked_at=clock_timestamp(),generation=generation+1 where company_id=$1 and user_id=$2 and active returning generation", [companyId, actorId])
    if (rows.rows.length !== 1) throw new Error("Membership unavailable.")
    await tx.query("insert into neuvetra_beta.audit(id,event_type,company_id,actor_id,membership_generation,decision_reference) values($1,'membership_revoked',$2,$3,$4,$5)", [crypto.randomUUID(), companyId, actorId, rows.rows[0]!.generation, decisionReference])
  })
}

export async function disableBetaAdmission(db: WorkspaceConnection, companyId: string, decisionReference: string, tombstone = false): Promise<void> {
  requireUuid(companyId, "Company")
  await db.transaction(async tx => {
    const rows = await tx.query<{ company_id: string }>(`update neuvetra_beta.tenant_admissions set active=false,tombstoned_at=case when $2 then coalesce(tombstoned_at,clock_timestamp()) else tombstoned_at end where company_id=$1 and active returning company_id`, [companyId, tombstone])
    if (rows.rows.length !== 1) throw new Error("Admission unavailable.")
    await tx.query("insert into neuvetra_beta.audit(id,event_type,company_id,decision_reference) values($1,$2,$3,$4)", [crypto.randomUUID(), tombstone ? "admission_tombstoned" : "admission_disabled", companyId, decisionReference])
  })
}

import type { WorkspaceConnection } from "./workspace"
import { readMigrationManifest } from "./staging-migrations"
import { BETA_ACCESS_PROFILE, BETA_ACCESS_SCHEMA_VERSION } from "./beta-access-contract"

export const BETA_ACCESS_MIGRATIONS = ["0001_access.sql"] as const

export async function readBetaAccessMigrationManifest() {
  return Promise.all(BETA_ACCESS_MIGRATIONS.map(async name => {
    const sql = (await Bun.file(new URL(`./beta-access-migrations/${name}`, import.meta.url)).text()).replace(/\r\n/g, "\n")
    return { name, sql, sha256: new Bun.CryptoHasher("sha256").update(sql).digest("hex") }
  }))
}

const safeName = /^[a-z][a-z0-9_]{7,62}$/
function quoteIdentifier(value: string): string { if (!safeName.test(value)) throw new Error("Unsafe local identifier."); return `"${value}"` }

export interface BetaAccessInstallApproval {
  databaseName: string
  runtimeRole: string
  fixtureManifestSha256: string
  syntheticTargetConfirmed: true
}

/** Explicit local operator action. The application never calls this function. */
export async function installBetaAccess(db: WorkspaceConnection, approval: BetaAccessInstallApproval) {
  if (approval.syntheticTargetConfirmed !== true || !approval.databaseName.startsWith("m80_beta_access_") || !approval.runtimeRole.startsWith("m80_beta_access_runtime_") || !safeName.test(approval.databaseName) || !safeName.test(approval.runtimeRole) || !/^[0-9a-f]{64}$/.test(approval.fixtureManifestSha256)) throw new Error("Exact synthetic beta target required.")
  const baseline = await readMigrationManifest()
  if (baseline.length !== 22) throw new Error("Schema 22 baseline required.")
  const module = await readBetaAccessMigrationManifest()
  await db.transaction(async tx => {
    await tx.query("select pg_advisory_xact_lock(802530001)")
    const target = await tx.query<{ database_name: string; current_user: string }>("select current_database() database_name,current_user")
    if (target.rows[0]?.database_name !== approval.databaseName || target.rows[0]?.current_user === approval.runtimeRole) throw new Error("Operator target mismatch.")
    const receipts = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra.schema_migrations order by name")
    if (receipts.rows.length !== baseline.length || receipts.rows.some((row, index) => row.name !== baseline[index]?.name || row.sha256 !== baseline[index]?.sha256)) throw new Error("Unknown or changed schema 22 baseline.")
    const role = await tx.query<{ safe: boolean }>("select not rolsuper and not rolinherit and not rolcreatedb and not rolcreaterole and not rolreplication and not rolbypassrls and not exists(select 1 from pg_auth_members where member=oid) safe from pg_roles where rolname=$1", [approval.runtimeRole])
    if (role.rows.length !== 1 || role.rows[0]?.safe !== true) throw new Error("Restricted beta runtime role required.")
    const present = await tx.query<{ present: boolean }>("select exists(select 1 from pg_namespace where nspname='neuvetra_beta') present")
    if (!present.rows[0]?.present) {
      await tx.exec(module[0]!.sql)
      await tx.query("insert into neuvetra_beta.target(profile,database_name,runtime_role,module_name,module_sha256,fixture_manifest_sha256) values($1,$2,$3,$4,$5,$6)", [BETA_ACCESS_PROFILE, approval.databaseName, approval.runtimeRole, module[0]!.name, module[0]!.sha256, approval.fixtureManifestSha256])
      for (const receipt of baseline) await tx.query("insert into neuvetra_beta.baseline_receipts(name,sha256) values($1,$2)", [receipt.name, receipt.sha256])
      await tx.query("insert into neuvetra_beta.schema_migrations(name,sha256) values($1,$2)", [module[0]!.name, module[0]!.sha256])
      const runtime = quoteIdentifier(approval.runtimeRole)
      await tx.exec(`grant usage on schema neuvetra_beta to ${runtime}; grant execute on function neuvetra_beta.redeem_invitation(text,uuid,text),neuvetra_beta.read_session(),neuvetra_beta.read_workspace(uuid) to ${runtime};`)
    } else {
      const existing = await tx.query<{ profile: string; database_name: string; runtime_role: string; module_name: string; module_sha256: string; fixture_manifest_sha256: string }>("select profile,database_name,runtime_role,module_name,module_sha256,fixture_manifest_sha256 from neuvetra_beta.target")
      const moduleReceipts = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra_beta.schema_migrations order by name")
      const copiedBaseline = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra_beta.baseline_receipts order by name")
      const e = existing.rows[0]
      if (existing.rows.length !== 1 || e?.profile !== BETA_ACCESS_PROFILE || e.database_name !== approval.databaseName || e.runtime_role !== approval.runtimeRole || e.module_name !== module[0]!.name || e.module_sha256 !== module[0]!.sha256 || e.fixture_manifest_sha256 !== approval.fixtureManifestSha256
        || moduleReceipts.rows.length !== 1 || moduleReceipts.rows[0]?.name !== module[0]!.name || moduleReceipts.rows[0]?.sha256 !== module[0]!.sha256
        || copiedBaseline.rows.length !== baseline.length || copiedBaseline.rows.some((row, index) => row.name !== baseline[index]?.name || row.sha256 !== baseline[index]?.sha256)) throw new Error("Unknown or changed beta access module.")
    }
  })
  return { profile: BETA_ACCESS_PROFILE, schemaVersion: BETA_ACCESS_SCHEMA_VERSION, migrations: module.map(({ name, sha256 }) => ({ name, sha256 })) }
}

create schema neuvetra_beta;
revoke all on schema neuvetra_beta from public;
alter default privileges in schema neuvetra_beta revoke all on tables from public;
alter default privileges in schema neuvetra_beta revoke all on sequences from public;
alter default privileges in schema neuvetra_beta revoke execute on functions from public;

create table neuvetra_beta.target (
  singleton boolean primary key default true check (singleton),
  profile text not null check (profile = 'neuvetra.beta-access.synthetic-rehearsal.v1'),
  database_name text not null,
  runtime_role text not null,
  module_name text not null check (module_name = '0001_access.sql'),
  module_sha256 text not null check (module_sha256 ~ '^[0-9a-f]{64}$'),
  fixture_manifest_sha256 text not null check (fixture_manifest_sha256 ~ '^[0-9a-f]{64}$')
);

create table neuvetra_beta.schema_migrations (
  name text primary key,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  applied_at timestamptz not null default clock_timestamp()
);

create table neuvetra_beta.baseline_receipts (
  name text primary key,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$')
);

create table neuvetra_beta.tenant_admissions (
  company_id uuid primary key references neuvetra.companies(id),
  admission_id uuid not null unique,
  fixture_manifest_sha256 text not null check (fixture_manifest_sha256 ~ '^[0-9a-f]{64}$'),
  display_label text not null check (display_label ~ '^[A-Za-z0-9 ._-]{1,80}$'),
  data_classification text not null check (data_classification = 'synthetic_rehearsal'),
  active boolean not null default true,
  tombstoned_at timestamptz,
  admitted_at timestamptz not null default clock_timestamp(),
  unique (company_id, admission_id),
  check (not active or tombstoned_at is null)
);

create table neuvetra_beta.invitations (
  id uuid primary key,
  company_id uuid not null,
  admission_id uuid not null,
  token_digest text not null unique check (token_digest ~ '^[0-9a-f]{64}$'),
  recipient_email text not null check (recipient_email = lower(btrim(recipient_email)) and recipient_email ~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,63}$'),
  role text not null check (role in ('owner', 'member')),
  status text not null default 'pending' check (status in ('pending', 'redeemed', 'revoked')),
  issued_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null,
  issuer_decision_reference text not null check (issuer_decision_reference ~ '^[A-Za-z0-9._:/-]{1,160}$'),
  redeemed_by uuid,
  redeemed_at timestamptz,
  redeemed_request_id uuid,
  unique (company_id, id),
  foreign key (company_id, admission_id) references neuvetra_beta.tenant_admissions(company_id, admission_id),
  check (expires_at > issued_at),
  check ((status = 'redeemed') = (redeemed_by is not null and redeemed_at is not null and redeemed_request_id is not null))
);

create table neuvetra_beta.memberships (
  company_id uuid not null references neuvetra_beta.tenant_admissions(company_id),
  user_id uuid not null,
  role text not null check (role in ('owner', 'member')),
  active boolean not null default true,
  source_invitation_id uuid not null,
  generation bigint not null default 1 check (generation > 0),
  admitted_at timestamptz not null default clock_timestamp(),
  revoked_at timestamptz,
  primary key (company_id, user_id),
  foreign key (company_id, source_invitation_id) references neuvetra_beta.invitations(company_id, id),
  check ((active and revoked_at is null) or (not active and revoked_at is not null))
);

create table neuvetra_beta.requests (
  actor_id uuid not null,
  request_id uuid not null,
  token_digest text not null check (token_digest ~ '^[0-9a-f]{64}$'),
  invitation_id uuid not null,
  company_id uuid not null,
  admission_id uuid not null,
  role text not null check (role in ('owner', 'member')),
  membership_generation bigint not null check (membership_generation > 0),
  committed_at timestamptz not null default clock_timestamp(),
  primary key (actor_id, request_id),
  foreign key (company_id, invitation_id) references neuvetra_beta.invitations(company_id, id),
  foreign key (company_id, actor_id) references neuvetra_beta.memberships(company_id, user_id)
);

create table neuvetra_beta.audit (
  id uuid primary key,
  event_type text not null check (event_type in ('admission_created', 'invitation_issued', 'invitation_redeemed', 'invitation_revoked', 'membership_revoked', 'admission_disabled', 'admission_tombstoned')),
  company_id uuid not null,
  invitation_id uuid,
  actor_id uuid,
  membership_generation bigint,
  created_at timestamptz not null default clock_timestamp(),
  decision_reference text not null check (decision_reference ~ '^[A-Za-z0-9._:/-]{1,160}$')
);

create function neuvetra_beta.assert_runtime_target() returns void
language plpgsql security definer
set search_path = pg_catalog, neuvetra_beta, auth, pg_temp
as $$
declare expected neuvetra_beta.target%rowtype;
begin
  select * into strict expected from neuvetra_beta.target;
  if current_database() <> expected.database_name or session_user <> expected.runtime_role then
    raise exception 'beta access unavailable' using errcode = '55000';
  end if;
  if not exists (
      select 1 from pg_roles r where r.rolname = expected.runtime_role
        and not r.rolsuper and not r.rolinherit and not r.rolcreatedb and not r.rolcreaterole
        and not r.rolreplication and not r.rolbypassrls
        and not exists (select 1 from pg_auth_members where member = r.oid)
    )
    or not has_schema_privilege(expected.runtime_role, 'neuvetra_beta', 'USAGE')
    or has_schema_privilege(expected.runtime_role, 'neuvetra_beta', 'CREATE')
    or has_schema_privilege(expected.runtime_role, 'neuvetra', 'USAGE')
    or has_schema_privilege(expected.runtime_role, 'auth', 'USAGE')
    or exists (
      select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
      where n.nspname in ('neuvetra_beta', 'neuvetra', 'auth') and c.relkind in ('r','p','v','m','f')
        and has_table_privilege(expected.runtime_role, c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
    )
    or exists (
      select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
      where n.nspname in ('neuvetra_beta', 'neuvetra', 'auth')
        and case when c.relkind = 'S' then has_sequence_privilege(expected.runtime_role, c.oid, 'USAGE,SELECT,UPDATE') else false end
    )
    or (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'neuvetra_beta' and has_function_privilege(expected.runtime_role, p.oid, 'EXECUTE')) <> 3
    or exists (
      select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'neuvetra_beta' and has_function_privilege(expected.runtime_role, p.oid, 'EXECUTE')
        and (p.proname, pg_get_function_identity_arguments(p.oid)) not in (
          ('redeem_invitation', 'token_digest text, request_id uuid, verified_email text'),
          ('read_session', ''),
          ('read_workspace', 'requested_company_id uuid')
        )
    ) then
    raise exception 'beta access unavailable' using errcode = '55000';
  end if;
  if (select count(*) from neuvetra.schema_migrations) <> 22
    or exists (
      (select name, sha256 from neuvetra.schema_migrations except select name, sha256 from neuvetra_beta.baseline_receipts)
      union all
      (select name, sha256 from neuvetra_beta.baseline_receipts except select name, sha256 from neuvetra.schema_migrations)
    )
    or (select count(*) from neuvetra_beta.schema_migrations where name = expected.module_name and sha256 = expected.module_sha256) <> 1
    or (select count(*) from neuvetra_beta.schema_migrations) <> 1 then
    raise exception 'beta access unavailable' using errcode = '55000';
  end if;
end $$;

create function neuvetra_beta.require_identity(actor uuid, supplied_email text) returns text
language plpgsql security definer
set search_path = pg_catalog, neuvetra_beta, auth, pg_temp
as $$
declare stored_email text;
begin
  if actor is null or supplied_email is null then
    raise exception 'invitation unavailable' using errcode = 'P0002';
  end if;
  select lower(btrim(email)) into stored_email
  from auth.users
  where id = actor and email_confirmed_at is not null and email is not null
  for update;
  if not found or stored_email <> supplied_email then
    raise exception 'invitation unavailable' using errcode = 'P0002';
  end if;
  return stored_email;
end $$;

create function neuvetra_beta.redeem_invitation(token_digest text, request_id uuid, verified_email text)
returns table(company_id uuid, role text, membership_generation bigint, state text, replayed boolean)
language plpgsql security definer
set search_path = pg_catalog, neuvetra_beta, auth, pg_temp
as $$
#variable_conflict use_column
declare
  actor uuid := auth.uid();
  normalized_email text := lower(btrim(verified_email));
  prior neuvetra_beta.requests%rowtype;
  invitation neuvetra_beta.invitations%rowtype;
  admission neuvetra_beta.tenant_admissions%rowtype;
  member neuvetra_beta.memberships%rowtype;
begin
  perform neuvetra_beta.assert_runtime_target();
  if token_digest !~ '^[0-9a-f]{64}$' or request_id is null or normalized_email !~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,63}$' then
    raise exception 'invitation unavailable' using errcode = 'P0002';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 80253));
  normalized_email := neuvetra_beta.require_identity(actor, normalized_email);

  select * into prior from neuvetra_beta.requests r where r.actor_id = actor and r.request_id = redeem_invitation.request_id;
  if found then
    if prior.token_digest <> redeem_invitation.token_digest then
      raise exception 'request conflict' using errcode = '23505';
    end if;
    select * into admission from neuvetra_beta.tenant_admissions a where a.company_id = prior.company_id for update;
    select * into invitation from neuvetra_beta.invitations i where i.id = prior.invitation_id for update;
    select * into member from neuvetra_beta.memberships m where m.company_id = prior.company_id and m.user_id = actor for update;
    if not found or not admission.active or admission.tombstoned_at is not null or admission.fixture_manifest_sha256 <> (select fixture_manifest_sha256 from neuvetra_beta.target)
      or admission.admission_id <> prior.admission_id
      or invitation.company_id <> prior.company_id or invitation.admission_id <> prior.admission_id
      or invitation.status <> 'redeemed' or invitation.recipient_email <> normalized_email or invitation.redeemed_by <> actor
      or invitation.redeemed_request_id <> prior.request_id or invitation.token_digest <> prior.token_digest
      or not member.active or member.generation <> prior.membership_generation or member.role <> prior.role
      or member.source_invitation_id <> prior.invitation_id then
      raise exception 'invitation unavailable' using errcode = 'P0002';
    end if;
    company_id := prior.company_id; role := prior.role; membership_generation := prior.membership_generation;
    state := 'access_admitted_setup_pending'; replayed := true; return next; return;
  end if;

  select * into invitation from neuvetra_beta.invitations i where i.token_digest = redeem_invitation.token_digest;
  if not found then raise exception 'invitation unavailable' using errcode = 'P0002'; end if;
  select * into admission from neuvetra_beta.tenant_admissions a where a.company_id = invitation.company_id for update;
  select * into invitation from neuvetra_beta.invitations i where i.id = invitation.id for update;
  if not found or not admission.active or admission.tombstoned_at is not null
    or admission.admission_id <> invitation.admission_id or admission.fixture_manifest_sha256 <> (select fixture_manifest_sha256 from neuvetra_beta.target)
    or invitation.status <> 'pending' or invitation.expires_at <= clock_timestamp() or invitation.recipient_email <> normalized_email then
    raise exception 'invitation unavailable' using errcode = 'P0002';
  end if;
  if exists (select 1 from neuvetra_beta.memberships m where m.company_id = invitation.company_id and m.user_id = actor) then
    raise exception 'invitation unavailable' using errcode = 'P0002';
  end if;
  insert into neuvetra_beta.memberships(company_id, user_id, role, source_invitation_id)
  values(invitation.company_id, actor, invitation.role, invitation.id)
  returning * into member;
  update neuvetra_beta.invitations set status = 'redeemed', redeemed_by = actor,
    redeemed_at = clock_timestamp(), redeemed_request_id = redeem_invitation.request_id where id = invitation.id;
  insert into neuvetra_beta.requests(actor_id, request_id, token_digest, invitation_id, company_id, admission_id, role, membership_generation)
  values(actor, redeem_invitation.request_id, redeem_invitation.token_digest, invitation.id, invitation.company_id, invitation.admission_id, invitation.role, member.generation);
  insert into neuvetra_beta.audit(id, event_type, company_id, invitation_id, actor_id, membership_generation, decision_reference)
  values(gen_random_uuid(), 'invitation_redeemed', invitation.company_id, invitation.id, actor, member.generation, invitation.issuer_decision_reference);
  company_id := invitation.company_id; role := invitation.role; membership_generation := member.generation;
  state := 'access_admitted_setup_pending'; replayed := false; return next;
end $$;

create function neuvetra_beta.read_session()
returns table(company_id uuid, role text, membership_generation bigint, display_label text, state text)
language plpgsql security definer
set search_path = pg_catalog, neuvetra_beta, auth, pg_temp
as $$
begin
  perform neuvetra_beta.assert_runtime_target();
  if auth.uid() is null then return; end if;
  perform neuvetra_beta.require_identity(auth.uid(), current_setting('request.jwt.claim.email', true));
  return query select m.company_id, m.role, m.generation, a.display_label, 'access_admitted_setup_pending'::text
  from neuvetra_beta.memberships m join neuvetra_beta.tenant_admissions a using(company_id)
  where m.user_id = auth.uid() and m.active and a.active and a.tombstoned_at is null
    and a.fixture_manifest_sha256 = (select fixture_manifest_sha256 from neuvetra_beta.target) order by m.company_id;
end $$;

create function neuvetra_beta.read_workspace(requested_company_id uuid)
returns table(company_id uuid, role text, membership_generation bigint, display_label text, state text)
language plpgsql security definer
set search_path = pg_catalog, neuvetra_beta, auth, pg_temp
as $$
begin
  perform neuvetra_beta.assert_runtime_target();
  if auth.uid() is null then return; end if;
  perform neuvetra_beta.require_identity(auth.uid(), current_setting('request.jwt.claim.email', true));
  return query select m.company_id, m.role, m.generation, a.display_label, 'access_admitted_setup_pending'::text
  from neuvetra_beta.memberships m join neuvetra_beta.tenant_admissions a using(company_id)
  where m.user_id = auth.uid() and m.company_id = requested_company_id and m.active and a.active and a.tombstoned_at is null
    and a.fixture_manifest_sha256 = (select fixture_manifest_sha256 from neuvetra_beta.target);
end $$;

revoke all on all tables in schema neuvetra_beta from public;
revoke all on all sequences in schema neuvetra_beta from public;
revoke all on all functions in schema neuvetra_beta from public;

do $$
declare table_name text;
begin
  foreach table_name in array array['target','schema_migrations','baseline_receipts','tenant_admissions','invitations','memberships','requests','audit'] loop
    execute format('alter table neuvetra_beta.%I enable row level security', table_name);
    execute format('alter table neuvetra_beta.%I force row level security', table_name);
    execute format('create policy owner_only on neuvetra_beta.%I using (current_user = pg_get_userbyid((select c.relowner from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=''neuvetra_beta'' and c.relname=%L))) with check (current_user = pg_get_userbyid((select c.relowner from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=''neuvetra_beta'' and c.relname=%L)))', table_name, table_name, table_name);
  end loop;
end $$;

import type { SupabaseClient } from "@supabase/supabase-js"

export interface VerifiedBetaIdentity { id: string; email: string }

/** Uses the provider's getUser response. Request claims and metadata are never identity authority. */
export async function validateBetaIdentity(token: string, client: SupabaseClient): Promise<VerifiedBetaIdentity | null> {
  const { data, error } = await client.auth.getUser(token)
  if (error || !data.user) return null
  const user = data.user as typeof data.user & { email_confirmed_at?: string | null; banned_until?: string | null; deleted_at?: string | null }
  if (!user.email || !user.email_confirmed_at || user.deleted_at) return null
  if (user.banned_until && Date.parse(user.banned_until) > Date.now()) return null
  return { id: user.id, email: user.email }
}

