import { BETA_ACCESS_PROFILE } from "../../../../packages/neuvetra-database/src/beta-access-contract"

export interface BetaAccessConfig {
  profile: typeof BETA_ACCESS_PROFILE
  origin: string
  databaseUrl: string
  databaseName: string
  runtimeRole: string
  port: number
}

function invalid(): never { throw new Error("Local beta access configuration is invalid.") }

/** Local-only. There is deliberately no hosted/staging environment switch or provider fallback. */
export function readBetaAccessConfig(environment: Record<string, string | undefined> = process.env): BetaAccessConfig {
  if (environment.NEUVETRA_BETA_ACCESS_ENABLED !== "local-synthetic-rehearsal" || environment.NEUVETRA_BETA_ACCESS_PROFILE !== BETA_ACCESS_PROFILE) invalid()
  const databaseName = environment.NEUVETRA_BETA_ACCESS_DATABASE ?? ""
  const runtimeRole = environment.NEUVETRA_BETA_ACCESS_RUNTIME_ROLE ?? ""
  if (!/^m80_beta_access_[a-z0-9_]{6,48}$/.test(databaseName) || !/^m80_beta_access_runtime_[a-z0-9_]{6,32}$/.test(runtimeRole)) invalid()
  let origin: URL, database: URL
  try { origin = new URL(environment.NEUVETRA_BETA_ACCESS_ORIGIN ?? ""); database = new URL(environment.NEUVETRA_BETA_ACCESS_DATABASE_URL ?? "") } catch { invalid() }
  if (origin.protocol !== "http:" || origin.hostname !== "127.0.0.1" || origin.origin !== environment.NEUVETRA_BETA_ACCESS_ORIGIN || origin.pathname !== "/" || origin.search || origin.hash) invalid()
  if (!(["postgres:", "postgresql:"].includes(database.protocol)) || database.hostname !== "127.0.0.1" || database.port !== "55472" || decodeURIComponent(database.username) !== runtimeRole || decodeURIComponent(database.pathname.slice(1)) !== databaseName || database.search || database.hash) invalid()
  const port = Number(environment.NEUVETRA_BETA_ACCESS_PORT ?? "3080")
  if (!Number.isInteger(port) || port < 1024 || port > 65535) invalid()
  return { profile: BETA_ACCESS_PROFILE, origin: origin.origin, databaseUrl: database.toString(), databaseName, runtimeRole, port }
}

import { BETA_ACCESS_PROFILE, BETA_ACCESS_UUID_PATTERN, parseBetaRedeemRequest } from "../../../../packages/neuvetra-database/src/beta-access-contract"
import { BetaDatabaseError, type BetaAccessDatabase } from "../../../../packages/neuvetra-database/src/beta-access"
import type { VerifiedBetaIdentity } from "./auth"

export const BETA_ACCESS_MAX_BODY_BYTES = 2048

function json(status: number, body: unknown): Response {
  return Response.json(body, { status, headers: { "cache-control": "no-store", "content-type": "application/json; charset=utf-8" } })
}

function databaseFailure(error: unknown): Response {
  if (error instanceof BetaDatabaseError && error.kind === "conflict") return json(409, { error: "Request conflict." })
  if (error instanceof BetaDatabaseError && error.kind === "unavailable") return json(404, { error: "Invitation unavailable." })
  return json(503, { error: "Beta access is unavailable." })
}

async function readBoundedBody(request: Request): Promise<string> {
  const reader = request.body?.getReader()
  if (!reader) return ""
  let size = 0
  const decoder = new TextDecoder("utf-8", { fatal: true })
  let body = ""
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      size += value.byteLength
      if (size > BETA_ACCESS_MAX_BODY_BYTES) { await reader.cancel(); throw new RangeError("body") }
      body += decoder.decode(value, { stream: true })
    }
    body += decoder.decode()
    return body
  } finally { reader.releaseLock() }
}

function parseStrictBody(source: string) {
  const keys = [...source.matchAll(/"([^"\\]*(?:\\.[^"\\]*)*)"\s*:/g)].map(match => match[1])
  if (keys.length !== 2 || keys.filter(key => key === "token").length !== 1 || keys.filter(key => key === "requestId").length !== 1) throw new SyntaxError("keys")
  return parseBetaRedeemRequest(JSON.parse(source))
}

export interface BetaRoutesDependencies {
  database: BetaAccessDatabase
  identity: VerifiedBetaIdentity
}

export async function handleBetaAccessRoute(request: Request, dependencies: BetaRoutesDependencies): Promise<Response> {
  const url = new URL(request.url)
  if (url.pathname === "/beta-api/invitations/redeem") {
    if (request.method !== "POST") return json(405, { error: "Method not allowed." })
    if (request.headers.get("content-type")?.split(";", 1)[0]?.trim().toLowerCase() !== "application/json") return json(415, { error: "JSON content required." })
    let source: string
    try { source = await readBoundedBody(request) } catch (error) { return error instanceof RangeError ? json(413, { error: "Request too large." }) : json(422, { error: "Invalid request." }) }
    let input
    try { input = parseStrictBody(source) } catch { return json(422, { error: "Invalid request." }) }
    const digest = new Bun.CryptoHasher("sha256").update(input.token).digest("hex")
    try {
      const result = await dependencies.database.redeem(dependencies.identity.id, dependencies.identity.email, digest, input.requestId)
      return json(result.replayed ? 200 : 201, { profile: BETA_ACCESS_PROFILE, ...result.access })
    } catch (error) { return databaseFailure(error) }
  }
  if (url.pathname === "/beta-api/session") {
    if (request.method !== "GET") return json(405, { error: "Method not allowed." })
    try { return json(200, { profile: BETA_ACCESS_PROFILE, access: await dependencies.database.readSession(dependencies.identity.id, dependencies.identity.email) }) } catch (error) { return databaseFailure(error) }
  }
  const match = url.pathname.match(/^\/beta-api\/workspaces\/([^/]+)$/)
  if (match) {
    if (request.method !== "GET") return json(405, { error: "Method not allowed." })
    if (!BETA_ACCESS_UUID_PATTERN.test(match[1]!)) return json(404, { error: "Workspace unavailable." })
    try {
      const access = await dependencies.database.readWorkspace(dependencies.identity.id, dependencies.identity.email, match[1]!)
      return access ? json(200, { profile: BETA_ACCESS_PROFILE, ...access }) : json(404, { error: "Workspace unavailable." })
    } catch (error) { return error instanceof BetaDatabaseError && error.kind === "dependency" ? databaseFailure(error) : json(404, { error: "Workspace unavailable." }) }
  }
  return json(404, { error: "Not found." })
}

import { extractBearerToken } from "../lib/auth"
import { BetaAccessDatabase } from "../../../../packages/neuvetra-database/src/beta-access"
import type { VerifiedBetaIdentity } from "./auth"
import type { BetaAccessConfig } from "./config"
import { handleBetaAccessRoute } from "./routes"

export interface BetaAccessLog { event: "request"; requestId: string; route: "redeem" | "session" | "workspace" | "unknown"; status: number; durationMs: number }
export interface BetaAccessServerOverrides {
  database?: BetaAccessDatabase
  validateIdentity: (token: string) => Promise<VerifiedBetaIdentity | null>
  log?: (event: BetaAccessLog) => void
  now?: () => number
}

export function createBetaRateLimiter(max: number, windowMs: number, maxBuckets: number, now: () => number) {
  const buckets = new Map<string, { start: number; count: number }>()
  return {
    check(key: string) {
      const timestamp = now()
      let bucket = buckets.get(key)
      if (!bucket) {
        if (buckets.size >= maxBuckets) {
          for (const [candidate, value] of buckets) {
            if (timestamp - value.start >= windowMs) buckets.delete(candidate)
          }
        }
        if (buckets.size >= maxBuckets) return false
        bucket = { start: timestamp, count: 0 }; buckets.set(key, bucket)
      } else if (timestamp - bucket.start >= windowMs) {
        bucket = { start: timestamp, count: 0 }; buckets.set(key, bucket)
      }
      bucket.count += 1
      return bucket.count <= max
    },
  }
}

function json(status: number, body: unknown) { return Response.json(body, { status }) }
function routeName(pathname: string): BetaAccessLog["route"] { return pathname.endsWith("/redeem") ? "redeem" : pathname.endsWith("/session") ? "session" : pathname.startsWith("/beta-api/workspaces/") ? "workspace" : "unknown" }

/** Composition only. Importing this module never connects, migrates, issues or listens. */
export async function createBetaAccessServer(config: BetaAccessConfig, overrides: BetaAccessServerOverrides) {
  const database = overrides.database ?? await BetaAccessDatabase.create({ connectionString: config.databaseUrl, databaseName: config.databaseName, runtimeRole: config.runtimeRole })
  const log = overrides.log ?? ((event: BetaAccessLog) => console.info(JSON.stringify(event)))
  const now = overrides.now ?? Date.now
  const global = createBetaRateLimiter(60, 60_000, 1, now)
  const actors = createBetaRateLimiter(5, 60_000, 1_000, now)
  try { await database.checkReadiness() } catch { await database.close(); throw new Error("Beta access dependency is unavailable.") }

  async function dispatch(request: Request): Promise<Response> {
    const url = new URL(request.url)
    if (!url.pathname.startsWith("/beta-api/")) return json(404, { error: "Not found." })
    if (request.headers.get("origin") !== config.origin) return json(403, { error: "Forbidden." })
    if (!global.check("server")) return json(429, { error: "Request limit reached." })
    const token = extractBearerToken(request.headers)
    if (!token || token.length > 8192) return json(401, { error: "Authentication required." })
    let identity: VerifiedBetaIdentity | null
    try { identity = await overrides.validateIdentity(token) } catch { return json(503, { error: "Authentication is unavailable." }) }
    if (!identity) return json(401, { error: "Authentication required." })
    if (url.pathname === "/beta-api/invitations/redeem" && !actors.check(identity.id)) return json(429, { error: "Request limit reached." })
    return handleBetaAccessRoute(request, { database, identity })
  }

  return {
    async fetch(request: Request) {
      const started = performance.now(), requestId = crypto.randomUUID(), pathname = new URL(request.url).pathname
      let response: Response
      try { response = await dispatch(request) } catch { response = json(503, { error: "Beta access is unavailable." }) }
      const headers = new Headers(response.headers)
      headers.set("cache-control", "no-store"); headers.set("x-request-id", requestId); headers.set("x-content-type-options", "nosniff")
      headers.set("referrer-policy", "no-referrer"); headers.set("x-frame-options", "DENY"); headers.set("content-security-policy", "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'")
      try { log({ event: "request", requestId, route: routeName(pathname), status: response.status, durationMs: Math.round(performance.now() - started) }) } catch { /* Logging cannot alter a committed response. */ }
      return new Response(response.body, { status: response.status, headers })
    },
    close: () => database.close(),
  }
}

